/* This test checks garbage collection when there are lots of
   attributed variables and pre-images on the trial.  */

test:-  make_chain(25),
	writeln('made the chain without seg faulting!').

make_chain(N):- 
	arc(_Var1,Var2,[before],i-i),
	make_chain(N,Var2).

make_chain(1,_Var1):- !.
make_chain(N,Var1):- 
	arc(Var1,Var2,[before],i-i),
	N1 is N - 1,
	make_chain(N1,Var2).


