%---------------------------------------------------- 72 delay_tests_cond_uncond
:- use_module(library(lists)).   % the dialect marker (see README): the oracle is swipl, so SCRIP reads this program as SWI-Prolog does
%--------------------------------------------------------------------------
%  This example tests the behaviour of the emulator when both a
%  conditional and an unconditional answer are derived for certain
%  subgoals.  The subgoals of interest are:
%	p(a,b) gets a conditional and then an unconditional answer;
%	this answer is returned to t(a,b) and should be simplified.
%  It requires no simplification after completion.  All simplification
%  should be early performed.  
%
%  --> All answers of t/2, p/2, and q/2 should be unconditional.
%--------------------------------------------------------------------------

:- table t/2, p/2, q/2, td/1.

t(X,Y) :- p(X,Y).
t(X,Y) :- q(X,Y).

p(a,X) :- td(X).
p(a,b).
p(a,c).

q(b,c).
q(b,b).
q(b,X) :- td(X).

td(X) :- sk_not(td(X)), X = b.

%--------------------------------------------------------------------------

test :- t(a,b), fail.
test :- t(a,b), write('1: Call t(a,b) '),
	( tnot(t(a,b)) -> writeln('is undefined') ; writeln('is true (OK)') ),
	fail.
test :-	abolish_all_tables, fail.
test :- t(b,b), fail.
test :- t(b,b), write('2: Call t(b,b) '),
	( tnot(t(b,b)) -> writeln('is undefined') ; writeln('is true (OK)') ),
	fail.
test :-	abolish_all_tables, fail.
test :- t(X,Y), write('3. Call t(X,Y) succeeds: '), writeln(t(X,Y)), fail.
/*--- Now retrieve answers from completed tables only ---*/
test :- p(X,Y), write('4. Call p(X,Y) succeeds: '), writeln(p(X,Y)), fail.
test :- q(X,Y), write('5. Call q(X,Y) succeeds: '), writeln(q(X,Y)), fail.
test :- t(X,Y), write('6. Call t(X,Y) succeeds: '), writeln(t(X,Y)), fail.
test.

% DRIVER (appended by the vendoring, CEO-700): XSB delay_tests/test.sh runs gentest.sh cond_uncond "test."
xsb_nonempty_line(L) :- string_length(L, N), N > 0. xsb_write_lines([]). xsb_write_lines([X|Xs]) :- write(X), nl, xsb_write_lines(Xs).
xsb_sorted_output(G) :- with_output_to(string(S), catch(ignore(G), E, print_message(error, E))), split_string(S, '\n', '', L0), include(xsb_nonempty_line, L0, L1), msort(L1, L), xsb_write_lines(L).
:- initialization(xsb_sorted_output((test))).
%------------------------------------------------------ 73 delay_tests_delay_var
:- use_module(library(lists)).   % the dialect marker (see README): the oracle is swipl, so SCRIP reads this program as SWI-Prolog does
%-----------------------------------------------------------------------
% To test delay lists with variables.
%-----------------------------------------------------------------------

:- import numbervars/1 from num_vars.
:- import get_residual/2 from tables.

test:- abolish_all_tables,fail.
test :-	test(C,D), numbervars((C,D)), 
	write(C),
	( D \== [] -> write(' :- ') ; true ),
	sort(D,Dsort),
	write('['), write_body(Dsort),
	fail.
test.

test(_,_) :- call_them, fail.
test(C,D) :- C = p(_,_), get_residual(C,D).
test(C,D) :- C = p2(_,_), get_residual(C,D).
test(C,D) :- C = r2(_,_), get_residual(C,D).
test(C,D) :- C = app1(_,_,_), get_residual(C,D).
test(C,D) :- C = reverse([_,_,_], _), get_residual(C,D).

%call_them :- p(_,_), p2(_,_), app1(_,_,_), reverse([_,_,_],_).
call_them :- p(_,_).
call_them :- p2(_,_).
call_them :- app1(_,_,_).
call_them :- reverse([_,_,_],_).

write_body([]) :- writeln('].').
write_body([H|T]) :- write(H), (T \== [] -> write(', ') ; true), write_body(T).

/*--------------------------------------------------------------------*/

:- table und/0.

und :- tnot(und).

:- table p/2, q/2, r/1, r/2.
:- table p2/2, q2/2, r2/2.
:- table app1/3, app/3.
:- table reverse/2.

p(f(88,X), _XX) :- q(X, f(Y,g(Z))), r(Y), Y=h(_DD,_EE,_FF), Z=fff(_).
%p(f(88,X), XX) :- q(X, f(Y,g(Z))), r(Y), Y=h(_DD,_EE,_FF), Z=fff(_),writeln(p(f(88,X),XX)).
p(_X, XX) :- r(XX, t(ZZ)), XX = fff(_SS,_TT), r(ZZ).
q(ggg(_X,Y,_Z,8),_) :- und, Y = 555.
r(_,_) :- und.
r(_) :- und.

p2(X,Y) :- q2(X,Y), r2(X,Y), X = 5.
p2(X,Y) :- r2(X,Y), X = 10.
q2(_,_) :- und.
r2(X,Y) :- q2(X,Y).

app1(X,Y,[A,B,C]) :- app(X,Y,[A,B,C]), A = 1, B = 2, C = 3.
app([], L, L) :- und.
app([X|L1], L2, [X|L3]) :- app(L1, L2, L3).


%-----------------------------------------------------------------------
% reverse/2 is written in this way to prevent specialization
%-----------------------------------------------------------------------
reverse(In, Result) :- In = [X], Result = [X], und.
reverse(In, Result) :- In = [Head|Tail],
