:- table t3/2 as subsumptive,incremental.
t3(X,Y) :- d3(X),Y is X + 10.
:- table t4/2 as subsumptive,incremental.
t4(X,Y) :- d4(X),Y is X + 10.
:- table t5/1 as subsumptive,incremental.
t5(f(g(X))) :- d5(X).
