t7(X,_Y) :- d7(X).
:- table t8/2 as subsumptive,incremental.
t8(X,_Y) :- d8(X).
:- table t9/2 as subsumptive,incremental.
t9(X,Y) :- d9(X),X = Y.
:- table t10/1 as subsumptive,incremental.
t10(X) :- d10(X).
:- table t11/3 as subsumptive,incremental.
t11(X,Y,Z) :- d11(X,Y,Z).

