:- import numbervars/1 from num_vars.

write_answers(Tag,Goal):- 
	get_residual(Goal,R),
	numbervars(get_residual(Goal,R)),
	write(Tag),write(' : '),write(Goal), write(' <- '),writeln(R),
	fail.
write_answers(_,_).

