tst4 :- fmt_write("asdsdffdsdgfdgf",_).
tst5 :- fmt_write('sdskdfdsffd %S sjdfdffd', sdkjfdsfjdfj).
tst6 :- fmt_write('ppsdfd %c %S sdfd', a(0'c, f(a,p(d,l)))).
