:- table p/1.
p(0):- writeln('finished test of p/1!').
p(N):- N1 is N - 1,p(N1).

loop(N):- loop(N,N).
:- table loop/2.
loop(0,N):- loop(N,N).
loop(0,N):- !,loop(0,N).
loop(N,M):- 
	N1 is N - 1,
	loop(N1,M).

sparse(N):- sparse(N,N).
:- table sparse/2.
sparse(0,N):- sparse(N,N).
sparse(M,N):- sparse(M,N).
sparse(N,M):- N >= 0,
	N1 is N - 1,
	sparse(N1,M).

dense(N):- dense(N,N).
:- table dense/2.
dense(0,_):- show_incomplete_subgoals,fail.
dense(N,M):- for(I,N,M),
	     %writeln(dense1(I,M)),
	     dense(I,M).
dense(N,M):- N >= 0,
	N1 is N - 1,
