:- op(500,xfx,==>).

at :- abolish_table_info.
 
:- at.

test:- first([s],5,F),writeln(F),fail.

% first(TNT,K,TList)
%first(_,0,[]).
%first([],_,[]).
first(_,_,[]).
first([Sym|Syms],K,F) :- K > 0,
        Sym ==> Bod,
        first(Bod,K,F0),
        length(F0,N), K1 is K-N,
        first(Syms,K1,F1), append(F0,F1,F).
first([Sym|Syms],K,[Sym|F]) :- K > 0,
        \+ (Sym ==> _),
        K1 is K-1, first(Syms,K1,F).


% first([s],3,L).
s ==> [a,s].
s ==> [a].


