makelist(0,[]):- !.
makelist(N,[_|T]):- 
    N1 is N - 1,
    makelist(N1,T).

make_term_list(0,_,[]):- !.
make_term_list(N,Arity,[Term|T]):- 
    N1 is N - 1,
    functor(Term,f,Arity),
    make_term_list(N1,Arity,T).

make_varlist_list(0,_,[]):- !.
make_varlist_list(N,Arity,[List|T]):- 
    N1 is N - 1, 
    makelist(Arity,List),
    make_varlist_list(N1,Arity,T).




