string_read(String,Term,Vars) :-
	file_open(String,3,File),
	file_read(File,Term,Vars),
	file_close(File).

string_call(String,Vars) :-
	str_cat(String,'.',Tstring),
	string_read(Tstring,Goal,Vars),
	Goal \== end_of_file,
	islist(Vars),
	call(Goal).

islist([]) :- !.
islist([_|L]) :- islist(L).

test_read_canonical :-
	see(readstrtest_data),
	repeat,
	read_canonical(X),
	(X == end_of_file
         ->    !,seen
         ;     numbervars(X,0,_),
	       writeln(X),
	       fail
	).

