:- table groundPattern/2 as incremental.
:- import variant_get_residual/2 from tables.

groundPattern([], []).
groundPattern([F|R],[true |RP]) :-
	nonvar(F),
	groundPattern(R,RP).
groundPattern([F|R],[false|RP]) :- 
	var(F),
	groundPattern(R,RP).

vcall_wrap(X) :-
	(call(X), fail
	;
	    (  variant_get_residual(X,[])
	    ;  fail
	    )
	).

call_wrap(X) :-
	(call(X), fail
	;
	    (  get_residual(X,[])
	    ;  fail
	    )
	).

