:- table win/1.
win(X):- move(X,Y),tnot(win(Y)).
move(N,N1):- 
     N = 10 -> 
       N1 = 0
     ; N1 is N + 1.

:- table pb/1.
pb(f(X)):- pb(X). %writeln(found(f(X))).
pb(a).

:- import u_not/1 from tables.
:- table pu/1.
pu(a):- u_not(p4(_)).

:- table p1/1, p1/1, p2/1, p3/1, p4/1, p5/1, p6/1, p7/1.

p1(X):- p2(X).
p1(X):- p4(X),p5(_).
%p1(X):- tnot(undefined),p4(X).
p1(X):- p3(X).

p2(X):- p4(X).
p2(X):- p5(X).

p3(X):- p6(X).
p3(X):- p7(X).

p4(a):- undefined.
p5(b):- undefined.
p6(c):- undefined.
p7(d):- undefined.

:- table n1/1, n2/1, n3/1,n4/1.
n1(X):- tnot(n2(X)),tnot(n4(X)).
n2(X):- tnot(n3(X)).
n3(_X):- undefined.
n4(_X):- fail.

:- table m1/1, m2/1, m3/1, m4/1.
m1(X):- m2(X).
m2(X):- m1(X).
m2(X):- m3(X).
m3(X):- tnot(m4(X)).
m4(X):- tnot(m3(X)).

