         (M = N,N = X -> write_it(tables:abstract_modes) ; true),q_7(X,N).

:- table q_8/2.
q_8(M,N):- between(1,N,X),
         (M = N,N = X -> write_scc ; true),q_8(X,N).

id_morph(T,T).

morph_2_(Term,NewTerm):- 
	Term =.. [F,A1,A2],
	map_arg_1(A1,NewA1),
	NewTerm =.. [F,NewA1,A2].

map_arg_1(2,1):- !.
map_arg_1(X,X).

