	writeln('---------------'),
	get_sdg_info(List),
%	writeln(List),
	morph_dep_graph(List,Morph,Listout),
	writeln(Listout).

write_scc:- 
	writeln('---------------'),
	get_sdg_info(List),
%	writeln(List),
	sdg_scc_info(List,Listout),
	writeln(Listout).

double_morph:- 
	writeln('---------------'),
	get_sdg_info(List),
%	writeln(List),
	morph_dep_graph(List,id_morph,List_1),
	morph_dep_graph(List_1,morph_2_,Listout),
	writeln(Listout).

