:- export test/0.

%easy aliases
a(X) :- trie_assert(X).
r(X) :- trie_retract(X).
ra(X) :- trie_retract_all(X).



test:- 
	write('Trie assert tests:'),
	test_retract,
	test_unary,
	test_binary,
	test_undef_retract,
	test_structures,
	test_cross_product,
	test_kostis_bug,
%	count_up_and_down,
	!,
	writeln('ok ')
	;
	writeln(' fail').

test_retract :-
	a(p001(1)),
	a(p001(2)),
	r(p001(2)),
	findall(X,p001(X),L),
	(L = [1] -> true; writeln(retract_failed(L,[1]))).

	

generate_ugly_structure(0, test_3_str(a,b,c)).
generate_ugly_structure(N,test_3_str(S,S,S)) :-
	N > 0,
	N1 is N - 1,
	generate_ugly_structure(N1,S).


test_structures:- 
	(
		numle(5,X),
		generate_ugly_structure(X,S),
		a(S),
		fail
	;
		true),
	(
		numle(5,Y),
		generate_ugly_structure(Y,S1),
		(call(S1)->true;writeln('Failure')),
		fail
	;
		true),
	ra(test_3_str(_,_,_)),
	\+ test_3_str(_,_,_).


test_cross_product:- 
	(
		numle(40,X),
		numle(40,Y),
		a(w_binary_1(X,Y)),
		fail
	;
		true),
	(	
		numle(40,X1),
		numle(40,Y1),
		(w_binary_1(X1,Y1)->true;writeln(failed)),
		fail
	;
		true),
	findall(X2,numle(40,X2),Lt40),
	findall_s(X3,w_binary_1(X3,27),Lt40),
	findall_s(X4,w_binary_1(27,X4),Lt40),
	(
		numle(40,X5),
		numle(40,Y5),
		r(w_binary_1(X5,Y5)),
		fail
	;
		true),
	findall(a(X6,Y6),w_binary_1(X6,Y6),[]).


