	TestNum = 200,
	findall(X1,numle(TestNum,X1),L),
	test_unary_1(TestNum,L),
	r(w_test_unary(23)),
	delete(23,L,L1),
	findall_s(X4,w_test_unary(X4),L1),
	LList = [1,34,56,91,75,83,199],
	trl1(LList),
